window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-654cc48ef23d266e"]={"versions": [{"id": "FIG-654cc48ef23d266e", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm / Schichtenarchitekturdiagramm des AUTOSAR Classic Platform Network Management Stacks für CAN. Es zeigt die vertikale Schichtung der Basissoftware-Module (BSW) innerhalb eines Steuergeräts (ECU).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Drei übereinander angeordnete BSW-Modulkomponenten («module»):</p>\n<ul class=\"fig-list\"><li><code>:Nm</code> (Generic Network Management Interface) auf oberster Ebene.\n</li><li><code>:CanNm</code> (CAN Network Management) in der mittleren Schicht.\n</li><li><code>:CanIf</code> (CAN Interface) auf unterster Schicht.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen oder Verbindungslinien zwischen den Modulen sind nicht explizit eingezeichnet; die Interaktion erfolgt implizit über die vertikale Schichtung.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine statische Schichtenarchitektur ohne Sequenzabläufe, Aufrufbeziehungen oder Nachrichtenflüsse dar. Die funktionale Kopplung erfolgt typischerweise durch standardisierte Funktionsaufrufe und Callback-Mechanismen zwischen Nm, CanNm und CanIf.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert die strukturelle Minimalanordnung des AUTOSAR-NM-Stacks auf CAN für ein Steuergerät mit mindestens einem CanNm-Cluster. CanNm interagiert nach oben mit der generischen NM-Koordinationsebene (:Nm) und nach unten direkt mit der CAN-Treiberschnittstelle (:CanIf).</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-0bccb52b7d4eda8c", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm / Schichtenarchitekturdiagramm des AUTOSAR Classic Platform Network Management Stacks für CAN. Es zeigt die vertikale Schichtung der Basissoftware-Module (BSW) einschließlich Routing-Unterstützung für große SDUs innerhalb eines Steuergeräts (ECU).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Vier vertikal gestapelte BSW-Modulkomponenten («module»):</p>\n<ul class=\"fig-list\"><li><code>&lt;u&gt;:Nm&lt;/u&gt;</code> (Generic Network Management Interface) auf oberster Ebene.\n</li><li><code>&lt;u&gt;:CanNm&lt;/u&gt;</code> (CAN Network Management) in der zweiten Schicht von oben.\n</li><li><code>LSduR</code> (Large SDU Router) als Zwischenschicht.\n</li><li><code>&lt;u&gt;:CanIf&lt;/u&gt;</code> (CAN Interface) auf unterster Schicht.\n</li></ul>\n<p class=\"fig-p\">Explizite Konnektoren oder Schnittstellenbeziehungen sind nicht dargestellt; die Interaktionskette ergibt sich aus der hierarchischen Schichtung.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine statische Schichtenarchitektur ohne Sequenzabläufe, Aufrufbeziehungen oder Nachrichtenflüsse dar. Die funktionale Kopplung erfolgt typischerweise durch standardisierte Funktionsaufrufe und Callback-Mechanismen zwischen Nm, CanNm und CanIf.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architekturvorgabe für den AUTOSAR-CAN-NM-Stack unter Einbindung des Moduls LSduR (Large SDU Router) zwischen CanNm und CanIf. Relevanter Hinweis für Integratoren und Entwickler bei der Übertragung von NM-Nachrichten bzw. Nutzerdaten, die die Standard-PDU-Länge überschreiten (Large SDU Handling).</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-654cc48ef23d266e", "to": "FIG-0bccb52b7d4eda8c", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Einfügung des Moduls «module» <code>LSduR</code> (Large SDU Router) in den Schichtenstapel zwischen <code>CanNm</code> und <code>CanIf</code>.\n</li><li>Änderung der UML-Notation der Modulbezeichner: <code>:Nm</code>, <code>:CanNm</code> und <code>:CanIf</code> sind unterstrichen (UML-Instanznotation), während das neu eingefügte Modul als ununterstrichenes <code>LSduR</code> dargestellt ist.\n</li></ul>"}]};
